        let lastSfxAt = {};

        function playSfx(id, options = {}) {
            const src = sfxSources[id];
            if (!src) return;
            const now = Date.now();
            const minGap = options.minGap ?? 280;
            if (lastSfxAt[id] && now - lastSfxAt[id] < minGap) return;
            lastSfxAt[id] = now;
            try {
                const audio = new Audio(src);
                audio.volume = Math.max(0, Math.min(1, options.volume ?? sfxVolumes[id] ?? 0.42));
                audio.currentTime = 0;
                const maxMs = options.maxMs === undefined ? (sfxMaxMs[id] ?? 900) : options.maxMs;
                const p = audio.play();
                if (p && typeof p.catch === "function") p.catch(() => {});
                if (maxMs !== null) {
                    setTimeout(() => {
                        try {
                            audio.pause();
                            audio.currentTime = 0;
                        } catch (err) {}
                    }, maxMs);
                }
            } catch (err) {}
        }

        function primeSfx() {
            Object.keys(sfxSources).forEach((id) => {
                try {
                    const audio = new Audio(sfxSources[id]);
                    audio.volume = 0;
                    const p = audio.play();
                    if (p && typeof p.then === "function") {
                        p.then(() => {
                            audio.pause();
                            audio.currentTime = 0;
                        }).catch(() => {});
                    }
                } catch (err) {}
            });
        }

        function playSceneLineSfx(sceneId, lineIndex) {
            if (pendingChoiceReaction) return;
            const ids = sceneLineSfx[`${sceneId}:${lineIndex}`];
            if (!ids) return;
            ids.forEach((id, i) => setTimeout(() => playSfx(id), i * 160));
        }

