        // ===== Scene background music =====
        // 씬별 BGM은 64kbps mono로 압축해 data URL로 삽입했다.
        // bgmSources moved to bgm_assets.js
        // bgmVolumes moved to bgm_assets.js
        // sceneBgmMap moved to bgm_assets.js

        let currentBgmKey = null;
        let currentBgmAudio = null;
        let bgmFadeTimer = null;

        function getBgmKey(sceneId) {
            if (!sceneId) return "S0";
            if (sceneBgmMap[sceneId]) return sceneBgmMap[sceneId];
            if (sceneId.startsWith("ENDING_BAD")) return "bad_ending";
            return sceneBgmMap[sceneId] || "S0";
        }

        function primeBgm() {
            try {
                const audio = new Audio(bgmSources["S0"]);
                audio.volume = 0;
                const p = audio.play();
                if (p && typeof p.then === "function") {
                    p.then(() => {
                        audio.pause();
                        audio.currentTime = 0;
                    }).catch(() => {});
                }
            } catch (err) {}
        }

        function playBgmForScene(sceneId, options = {}) {
            const key = getBgmKey(sceneId);
            const src = bgmSources[key];
            if (!src) return;

            const targetVolume = Math.max(0, Math.min(1, options.volume ?? bgmVolumes[key] ?? 0.33));
            const fadeMs = options.fadeMs ?? 900;

            if (currentBgmKey === key && currentBgmAudio && !currentBgmAudio.paused) {
                currentBgmAudio.volume = targetVolume;
                return;
            }

            const startNew = () => {
                try {
                    const audio = new Audio(src);
                    currentBgmAudio = audio;
                    currentBgmKey = key;
                    audio.loop = true;
                    audio.volume = 0;
                    const p = audio.play();
                    if (p && typeof p.catch === "function") p.catch(() => {});
                    const steps = Math.max(1, Math.floor(fadeMs / 50));
                    let n = 0;
                    clearInterval(bgmFadeTimer);
                    bgmFadeTimer = setInterval(() => {
                        n += 1;
                        if (!currentBgmAudio || currentBgmAudio !== audio) {
                            clearInterval(bgmFadeTimer);
                            return;
                        }
                        audio.volume = Math.min(targetVolume, targetVolume * (n / steps));
                        if (n >= steps) {
                            audio.volume = targetVolume;
                            clearInterval(bgmFadeTimer);
                        }
                    }, 50);
                } catch (err) {}
            };

            if (currentBgmAudio && !currentBgmAudio.paused) {
                const oldAudio = currentBgmAudio;
                const startVolume = oldAudio.volume || targetVolume;
                const steps = Math.max(1, Math.floor(fadeMs / 50));
                let n = 0;
                clearInterval(bgmFadeTimer);
                bgmFadeTimer = setInterval(() => {
                    n += 1;
                    try {
                        oldAudio.volume = Math.max(0, startVolume * (1 - n / steps));
                    } catch (err) {}
                    if (n >= steps) {
                        clearInterval(bgmFadeTimer);
                        try {
                            oldAudio.pause();
                            oldAudio.currentTime = 0;
                        } catch (err) {}
                        startNew();
                    }
                }, 50);
            } else {
                startNew();
            }
        }

        function stopBgm(fadeMs = 700) {
            if (!currentBgmAudio) return;
            const audio = currentBgmAudio;
            const startVolume = audio.volume || 0.33;
            const steps = Math.max(1, Math.floor(fadeMs / 50));
            let n = 0;
            clearInterval(bgmFadeTimer);
            bgmFadeTimer = setInterval(() => {
                n += 1;
                try {
                    audio.volume = Math.max(0, startVolume * (1 - n / steps));
                } catch (err) {}
                if (n >= steps) {
                    clearInterval(bgmFadeTimer);
                    try {
                        audio.pause();
                        audio.currentTime = 0;
                    } catch (err) {}
                    if (currentBgmAudio === audio) {
                        currentBgmAudio = null;
                        currentBgmKey = null;
                    }
                }
            }, 50);
        }


        function getEndingVideoKey(sceneId) {
            if (sceneId === "ENDING_TRUE") return "true_ending";
            if (sceneId === "ENDING_NORMAL") return "normal_ending";
            if (sceneId && sceneId.startsWith("ENDING_BAD")) return "bad_ending";
            return null;
        }

        async function playCinematicVideo(videoKey) {
            const src = cinematicVideos[videoKey];
            const overlay = document.getElementById('cinematic-overlay');
            const video = document.getElementById('cinematic-video');
            if (!src || !overlay || !video) return;

            return new Promise((resolve) => {
                let finished = false;
                let fallbackTimer = null;

                const finish = () => {
                    if (finished) return;
                    finished = true;
                    clearTimeout(fallbackTimer);
                    overlay.classList.add('fading-out');
                    overlay.classList.remove('active');

                    setTimeout(() => {
                        try {
                            video.pause();
                            video.removeAttribute('src');
                            video.load();
                        } catch (err) {}
                        overlay.style.display = "none";
                        overlay.setAttribute('aria-hidden', 'true');
                        overlay.classList.remove('fading-out');
                        const gameContainer = document.getElementById('game-container');
                        if (gameContainer) gameContainer.classList.remove('video-playing');
                        overlay.onclick = null;
                        video.onended = null;
                        video.onerror = null;
                        resolve();
                    }, 720);
                };

                const gameContainer = document.getElementById('game-container');
                if (gameContainer) gameContainer.classList.add('video-playing');

                overlay.style.display = "flex";
                overlay.setAttribute('aria-hidden', 'false');
                overlay.classList.remove('fading-out');
                video.src = src;
                video.muted = true;
                video.controls = false;
                video.playsInline = true;
                video.currentTime = 0;
                video.onended = finish;
                video.onerror = finish;
                overlay.onclick = finish;

                requestAnimationFrame(() => {
                    overlay.classList.add('active');
                });

                const playPromise = video.play();
                if (playPromise && typeof playPromise.catch === "function") {
                    playPromise.catch(() => {
                        setTimeout(finish, 500);
                    });
                }

                fallbackTimer = setTimeout(finish, 30000);
            });
        }
