        async function handleNext() {
            if (isTyping) {
                skipTyping();
                return;
            }
            if (isWaitingForChoice || isTransitioning) return;
            if (seqIdx >= getActiveSeq().length) {
                if (pendingChoiceReaction) {
                    const next = pendingChoiceReaction.next;
                    pendingChoiceReaction = null;
                    seqIdx = 0;
                    moveScene(next);
                }
                return;
            }
            hideContinueIndicator();

            // 새 씬으로 넘어왔는데 visual이 아직 이전 무대인 경우 → 커튼 효과로 무대 전환
            if (displayedSceneVisual !== currentScene) {
                isTransitioning = true;
                const stage = document.getElementById('stage');

                // 1. 커튼 닫기 - 닫히는 동안 텍스트는 그대로 유지(커튼이 가림)
                stage.classList.add('curtain-closed');
                await sleep(1100);  // 닫힘 트랜지션 거의 끝까지

                // 2. 닫힌 채 짧은 정지 - 텍스트 박스 비우고 visual만 미리 갱신
                await sleep(220);
                displayedSceneVisual = currentScene;
                document.getElementById('text-content').innerText = "";
                document.getElementById('name-tag').innerText = "";
                // visual + bg + vignette 미리 갱신 (커튼 뒤에 숨김)
                const visualSymbol = document.getElementById('visual-symbol');
                visualSymbol.innerText = "";
                visualSymbol.style.opacity = "0";
                hideCharacterSprite();
                applySceneBackground(displayedSceneVisual, 0);
                updateVignette(displayedSceneVisual);

                // 3. 커튼 열기 - 커튼이 거의 다 열린 시점부터 텍스트 시작 (불필요한 대기 줄임)
                stage.classList.remove('curtain-closed');
                await sleep(900);

                // 4. 텍스트 타이핑 시작
                renderScene();
                isTransitioning = false;
            } else {
                renderScene();
            }
        }

        function renderChoices() {
            document.getElementById('game-container').classList.add('choice-mode');
            hideContinueIndicator();
            isWaitingForChoice = true; const area = document.getElementById('choice-area'); area.innerHTML = "";
            scenario[currentScene].choices.forEach(c => {
                if (c.condition && !c.condition()) return;
                const btn = document.createElement('div'); btn.className = "choice-btn"; btn.innerText = c.text;
                btn.onclick = (e) => {
                    e.stopPropagation();
                    if (isTransitioning) return;
                    playChoiceSfx(currentScene, c);
                    if (c.effect) applyEffect(c.effect);
                    if (isGameOver) return;

                    const reaction = getChoiceReaction(currentScene, c);
                    if (reaction && reaction.length) {
                        pendingChoiceReaction = { next: c.next, seq: reaction };
                        isWaitingForChoice = false;
                        document.getElementById('game-container').classList.remove('choice-mode');
                        document.getElementById('choice-area').innerHTML = "";
                        hideContinueIndicator();
                        seqIdx = 0;
                        renderScene();
                    } else {
                        moveScene(c.next);
                    }
                }; area.appendChild(btn);
            });
        }

        function applyEffect(eff) {
            const before = {
                ribbon: state.ribbon,
                watch: state.watch,
                key: state.key,
                key_revealed: state.key_revealed,
                trade_items: [...getTradeItems()]
            };
            for (let k in eff) {
                if (k === 'trade_item') addTradeItem(eff[k]);
                else if (k === 'remove_trade_item') removeTradeItem(eff[k]);
                else if (typeof state[k] === 'number') state[k] += eff[k];
                else state[k] = eff[k];
            }
            if (state.vit <= 0 || state.san <= 0 || state.str >= 100) forceGameOver();
            else { 
                state.vit = Math.max(0, Math.min(100, state.vit)); 
                state.san = Math.max(0, Math.min(100, state.san)); 
                state.str = Math.max(0, state.str); 
                updateUI(); 
            }
            showItemToasts(before);
        }

        // 토스트 큐 - 알림이 겹치지 않게 한 번에 하나씩, 1초 간격으로 처리
        const _toastQueue = [];
        let _toastSchedulerActive = false;
        function _runNextToast() {
            if (_toastQueue.length === 0) {
                _toastSchedulerActive = false;
                return;
            }
            const text = _toastQueue.shift();
            const area = document.getElementById('item-toast-area');
            const wrapper = document.createElement('div');
            wrapper.className = "item-toast-wrapper";
            wrapper.innerHTML =
                '<div class="item-toast-rope left"></div>' +
                '<div class="item-toast-rope right"></div>' +
                '<div class="item-toast-board"></div>';
            wrapper.querySelector('.item-toast-board').innerText = text;
            area.appendChild(wrapper);
            // 애니메이션 끝나면 DOM에서 제거
            setTimeout(() => {
                if (wrapper.parentNode) wrapper.parentNode.removeChild(wrapper);
            }, 2900);
            // 다음 토스트는 1.0초 후 시작 - 첫 토스트가 안정 상태에 들어간 후
            setTimeout(_runNextToast, 1000);
        }

        function showItemToasts(before) {
            const itemNames = { ribbon: "어머니의 리본", watch: "언니의 회중시계" };
            const tradeNames = {
                spade_token: "스페이드 왕의 검은 표식",
                diamond_gem: "반짝이는 보석 조각",
                clover_rose: "여왕의 붉은 장미"
            };
            const queueToast = (text) => {
                _toastQueue.push(text);
                if (!_toastSchedulerActive) {
                    _toastSchedulerActive = true;
                    _runNextToast();
                }
            };

            // 일반 아이템 (ribbon, watch)
            ["ribbon", "watch"].forEach(k => {
                if (before[k] === state[k]) return;
                const verb = state[k] ? "획득" : "상실";
                queueToast(`${verb}: ${itemNames[k]}`);
            });

            // key (잡동사니/황금열쇠) - 정체 여부에 따라 표기 다름
            if (before.key !== state.key) {
                if (state.key) {
                    const keyName = state.key_revealed ? "황금 열쇠" : "흙 묻은 잡동사니";
                    queueToast(`획득: ${keyName}`);
                } else {
                    const lostName = before.key_revealed ? "황금 열쇠" : "흙 묻은 잡동사니";
                    queueToast(`상실: ${lostName}`);
                }
            } else if (!before.key_revealed && state.key_revealed) {
                // key 자체는 그대로지만 정체가 드러남 (모자장수)
                queueToast(`정체 확인: 황금 열쇠`);
            }

            // 교환 아이템은 여러 개 보유 가능하므로 배열 차이로 획득/상실을 표시
            const beforeTrades = Array.isArray(before.trade_items) ? before.trade_items : [];
            const afterTrades = getTradeItems();
            afterTrades.forEach(item => {
                if (!beforeTrades.includes(item)) queueToast(`획득: ${tradeNames[item]}`);
            });
            beforeTrades.forEach(item => {
                if (!afterTrades.includes(item)) queueToast(`상실: ${tradeNames[item]}`);
            });
        }

        function sleep(ms) { return new Promise(r => setTimeout(r, ms)); }

        async function returnToTitle(e) {
            if (e) e.stopPropagation();
            if (isTransitioning) return;
            stopBgm(700);
            isTransitioning = true;
            // 버튼 즉시 사라지게 (롤백 느낌)
            const btn = document.getElementById('ending-return-btn');
            btn.classList.remove('show');
            btn.style.opacity = "0";
            btn.style.pointerEvents = "none";
            // 커튼 내림 - 공연이 끝나고 막이 내려가는 연출
            const stage = document.getElementById('stage');
            stage.classList.add('curtain-closed');
            await sleep(1200);
            await sleep(400);
            // 화면 어둡게 + 새 공연을 위한 리로드
            document.body.style.transition = "opacity 0.45s ease";
            document.body.style.opacity = "0";
            await sleep(450);
            location.reload();
        }

        function getNormalEndingText() {
            const tradeNames = {
                spade_token: "낯선 검은 쇠 조각이",
                diamond_gem: "이상한 보석 한 알이",
                clover_rose: "페인트 자국이 남은 시든 장미 한 송이가"
            };
            let parts = ["언니가 깨우는 소리에 앨리스는 천천히 눈을 떴습니다."];
            if (state.ribbon) {
                parts.push("머리에 손을 가져가 보니, 어머니의 리본이 여전히 단정히 매여 있었지요.");
            } else {
                parts.push("머리에 손을 가져가 보니, 그 자리에 매여 있어야 할 리본은 어디에도 없었답니다.");
            }
            if (state.watch) {
                parts.push("가슴께를 더듬자 회중시계가 똑딱똑딱 흐르고 있었어요. 다만 한 박자, 잠시 거꾸로 흔들리는 듯했지요.");
            } else {
                parts.push("가슴께에는 째깍거림이 사라진 빈자리만이 시리게 남아 있었답니다.");
            }
            const carriedTrades = getTradeItems();
            if (carriedTrades.length > 0) {
                const carriedText = carriedTrades.map(item => tradeNames[item]).filter(Boolean).join(", ");
                parts.push(`그러나 주머니 속에는 ${carriedText} 만져졌어요. 분명 풀밭으로 가져온 적 없는 물건들이었지요.`);
            }
            parts.push("모든 게 꿈 같았지만, 가슴 한구석의 허전함이 좀처럼 가시지 않았답니다.");
            return parts.join(" ");
        }

        function getTrueEndingText() {
            const tradeNames = {
                spade_token: "스페이드 왕의 검은 표식",
                diamond_gem: "다이아 왕의 보석 조각",
                clover_rose: "클로버 여왕의 붉은 장미"
            };
            let recovered = [];
            if (!state.ribbon) recovered.push("어머니의 리본이 다시 머리에 단정히 묶여 있었지요");
            if (!state.watch) recovered.push("가슴께에서 언니의 회중시계가 다시 정상적인 박자로 째깍거리기 시작했답니다");
            const carriedTrades = getTradeItems();
            if (carriedTrades.length > 0) recovered.push(`주머니 속의 ${carriedTrades.map(item => tradeNames[item]).filter(Boolean).join(", ")}은 빛 속에서 먼지처럼 흩어져 사라졌어요`);
            const recoveryText = recovered.length > 0
                ? "그 황금빛을 따라, 잃어버렸던 것들이 하나씩 제자리로 돌아왔어요. " + recovered.join(". ") + ". "
                : "";
            return "황금 열쇠가 마지막 문에 들어맞자, 사방의 카드들이 한 장 한 장 종이처럼 흩어졌습니다. "
                 + recoveryText
                 + "앨리스는 강가의 풀밭에서 천천히 눈을 떴답니다. 손에는 여전히 그 작은 황금 열쇠가 단단히 쥐어져 있었지요. 정말 꿈이었을까요?";
        }

        async function moveScene(id) {
            pendingChoiceReaction = null;
            document.getElementById('game-container').classList.remove('choice-mode');
            if (id === "RELOAD") { location.reload(); return; }
            if (id === "CHECK_ENDING") id = (state.san >= 60 && state.vit >= 50) ? "ENDING_NORMAL" : "ENDING_BAD";
            hideContinueIndicator();

            const isEnding = id.startsWith("ENDING");

            if (isEnding) {
                // 엔딩 진입 - 즉시 커튼 막 내림 (피날레)
                isTransitioning = true;
                const stage = document.getElementById('stage');

                // 1. 커튼 닫기
                stage.classList.add('curtain-closed');
                await sleep(1100);

                // 2. 닫힌 채 짧은 정지 + 새 데이터 준비 + 텍스트/이름표 비우기
                await sleep(220);
                currentScene = id; seqIdx = 0; isWaitingForChoice = false;
                playBgmForScene(currentScene, { fadeMs: 1100 });
                document.getElementById('choice-area').innerHTML = "";
                const res = { 
                    "ENDING_TRUE": getTrueEndingText(),
                    "ENDING_NORMAL": getNormalEndingText(),
                    "ENDING_BAD": "배드엔딩: 앨리스가 눈을 감자 하트 여왕은 따분하다는 듯 손가락을 내렸습니다. 마음에 들지 않는 침묵이라는 이유만으로 판결은 끝났고, 앨리스는 하트 정원의 하얀 카드 한 장이 되어 자신이 누구였는지조차 잊게 되었습니다.",
                    "ENDING_BAD_SPADE": "배드엔딩: 스페이드 왕의 검은 표식을 펴 보이자, 하트 여왕은 웃지도 않았습니다. \"남의 왕관 뒤에 숨는 얼굴은 더 마음에 들지 않는다. 치워라.\" 카드 병정들이 앨리스를 끌고 갔고, 검은 광산의 문은 다시는 열리지 않았답니다.",
                    "ENDING_BAD_DIAMOND": "배드엔딩: 반짝이는 보석을 내밀자, 하트 여왕은 보석보다 앨리스의 떨리는 손을 더 싫어했습니다. \"내 마음에 들지 않는 빛은 꺼 버리면 된다.\" 보석은 짓밟혔고, 앨리스의 길도 함께 어둠 속으로 꺼졌습니다.",
                    "ENDING_BAD_CLOVER": "배드엔딩: 붉은 장미를 바치자 하트 여왕은 꽃잎의 페인트 자국을 보고 눈썹을 치켜올렸습니다. \"가짜 붉음은 진짜 벌을 부르지.\" 앨리스는 흰 카드 한 장이 되어, 영원히 붉은 페인트를 칠하게 되었답니다."
                };
                scenario[id] = { visual: "🏁", seq: [{ name: "결말", text: res[id] }], choices: [] };
                displayedSceneVisual = id;
                document.getElementById('text-content').innerText = "";
                document.getElementById('name-tag').innerText = "";
                // visual만 미리 갱신
                hideCharacterSprite();
                document.getElementById('visual-symbol').innerText = "";
                document.getElementById('visual-symbol').style.opacity = "0";
                applySceneBackground(id, 0);
                updateVignette(id);

                // 3. 엔딩 영상 재생 - 엔딩 나레이션 전에 자연스럽게 먼저 보여준다.
                await playCinematicVideo(getEndingVideoKey(id));
                await sleep(240);

                // 4. 커튼 열기
                stage.classList.remove('curtain-closed');
                await sleep(900);

                // 5. 텍스트 타이핑
                renderScene();
                isTransitioning = false;
            } else {
                // 일반 씬 전환: 선택 직후 먼저 커튼을 닫고, 새 무대를 준비한 뒤 첫 대사를 시작한다.
                // 이전 버전처럼 새 씬의 첫 대사가 이전 배경 위에 뜨는 문제를 막는다.
                isTransitioning = true;
                const stage = document.getElementById('stage');
                stage.classList.add('curtain-closed');
                await sleep(1050);

                currentScene = id; seqIdx = 0; isWaitingForChoice = false;
                playBgmForScene(currentScene, { fadeMs: 900 });
                displayedSceneVisual = id;
                document.getElementById('choice-area').innerHTML = "";
                document.getElementById('text-content').innerText = "";
                document.getElementById('name-tag').innerText = "";

                const visualSymbol = document.getElementById('visual-symbol');
                visualSymbol.innerText = "";
                visualSymbol.style.opacity = "0";
                hideCharacterSprite();
                applySceneBackground(displayedSceneVisual, 0);
                updateVignette(displayedSceneVisual);

                await sleep(180);
                stage.classList.remove('curtain-closed');
                await sleep(760);
                renderScene();
                isTransitioning = false;
            }
        }

        function forceGameOver() {
            isGameOver = true; 
            displayedSceneVisual = currentScene;  // 동기화
            let reason = state.vit <= 0 ? "탈진: 앨리스의 몸이 바닥으로 쓰러집니다. 이상한 나라의 흙이 그녀를 조용히 덮어버립니다." : 
                         state.san <= 0 ? "발광: 앨리스는 정신을 놓고 웃기 시작했습니다. 그녀는 이제 영원히 이곳의 일부가 되었습니다." : 
                         "쇼크: 심장이 터질 듯한 공포가 앨리스를 덮쳤습니다. 그녀의 시간은 여기서 멈췄습니다.";
            hideCharacterSprite();
            document.getElementById('visual-symbol').innerText = "💀";
            document.getElementById('visual-symbol').style.opacity = "1";
            document.getElementById('name-tag').innerText = "게임 오버";
            document.getElementById('text-content').innerText = reason; 
            document.getElementById('choice-area').innerHTML = `<div class="choice-btn" onclick="location.reload()">타이틀로 돌아가기 (다시 시작)</div>`;
            updateUI();
            document.getElementById('game-container').classList.add('choice-mode');
        }

        // 페이지 로드 시 타이틀 커튼 열기 (한 번만)
        function openInitialTitleCurtain() {
            const titleCurtain = document.getElementById('title-curtain');
            if (!titleCurtain || titleCurtain.dataset.opened === "true") return;
            titleCurtain.dataset.opened = "true";

            // 시작하기 버튼을 누르기 전, 타이틀 화면 커튼이 확실히 열리도록 한다.
            requestAnimationFrame(() => {
                setTimeout(() => {
                    titleCurtain.classList.add('opened');
                }, 180);
            });

            setTimeout(() => {
                titleCurtain.classList.add('gone');
            }, 1900);

            // 안전장치: 어떤 이유로든 transition이 안 먹으면 커튼을 강제로 제거.
            setTimeout(() => {
                titleCurtain.classList.add('opened');
                titleCurtain.classList.add('gone');
            }, 2800);
        }

        if (document.readyState === "loading") {
            document.addEventListener('DOMContentLoaded', openInitialTitleCurtain);
        } else {
            openInitialTitleCurtain();
        }
        window.addEventListener('load', openInitialTitleCurtain);

(function(){
            function forceOpenTitleCurtain(){
                var c = document.getElementById('title-curtain');
                if (!c) return;
                setTimeout(function(){ c.classList.add('opened'); }, 120);
                setTimeout(function(){ c.classList.add('gone'); }, 1900);
                setTimeout(function(){ c.style.display = 'none'; }, 2600);
            }
            if (document.readyState === 'loading') {
                document.addEventListener('DOMContentLoaded', forceOpenTitleCurtain);
            } else {
                forceOpenTitleCurtain();
            }
            window.addEventListener('load', forceOpenTitleCurtain);
        })();
